class TripsPage extends StatelessWidget { const TripsPage({super.key}); @override Widget build(BuildContext context) => DefaultTabController(length: 4, child: Column(children: [
  Padding(padding: const EdgeInsets.fromLTRB(20,18,20,8), child: Row(children:[Expanded(child: Text('الرحلات',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900))),IconButton(onPressed:(){},icon:const Icon(Icons.search_rounded))])),
